import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const fakeDelete = (id) => new Promise((res) => setTimeout(() => res(true), 200));

function App() {
  const [items, setItems] = useState([
    { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }, { id: "p3", name: "Ном" },
  ]);

  function remove(id) {
    fakeDelete(id).then(() => {
      setItems((prev) => prev.filter((x) => x.id !== id));
    });
  }

  return (
    <View style={styles.s}>
      {items.map((it) => (
        <View key={it.id} style={styles.row}>
          <Text testID="row">{it.name}</Text>
          <Pressable testID="del" onPress={() => remove(it.id)}><Text style={styles.x}>Устгах</Text></Pressable>
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  row: { flexDirection: "row", justifyContent: "space-between", alignItems: "center", paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
  x: { color: "#dc2626", fontWeight: "bold" },
});

registerRootComponent(App);
